-- =============================================================
-- DATOS DE PRUEBA (LEGACY) — core-service
-- Contraseña de todos los usuarios: Test1234
-- Código de seguridad (security_code) de todos los clientes: 123456
--   (almacenado bcrypteado, igual que en ClientService.createSecurityCode)
-- Volumen: 8 admins + 200 clientes, historial 2015-2026.
-- =============================================================

-- USUARIOS (8 admins + 200 clientes)
ON CONFLICT (dni) DO NOTHING;

-- CLIENTES (tarjeta + security_code bcrypt('123456'))
ON CONFLICT (dni) DO NOTHING;

-- PREGUNTAS del cuestionario de onboarding
ON CONFLICT (wording) DO NOTHING;

SELECT setval(pg_get_serial_sequence('questions', 'id_question'), (SELECT MAX(id_question) FROM questions), true);

-- RESPUESTAS de los clientes al cuestionario (unique (dni, question_id))
ON CONFLICT (dni, question_id) DO NOTHING;

SELECT setval('client_answer_seq', (SELECT COALESCE(MAX(id_client_answer),1) FROM client_answer) + 50, true);

-- VENTAS (id_artwork referencia IDs del artwork-service en MongoDB)
ON CONFLICT (id_sale) DO NOTHING;

SELECT setval(pg_get_serial_sequence('sale', 'id_sale'), (SELECT MAX(id_sale) FROM sale), true);

-- PAGOS (solo para ventas con estado APPROVED)
ON CONFLICT (id_sale) DO NOTHING;

-- MEMBRESÍAS (historial de renovaciones; máximo una ACTIVE por cliente)
ON CONFLICT (id_membership) DO NOTHING;

SELECT setval(pg_get_serial_sequence('memberships', 'id_membership'), (SELECT MAX(id_membership) FROM memberships), true);
